// Command codemap keeps the code map up to date: it writes a generated "Codemap" section into every package's
// doc.go and copies those sections, plus a directory tree, into CODEMAP.md at the repo root.
//
// Run `go run ./cmd/codemap` after changing code. `-check` fails if any generated file is stale (the test suite runs
// it), `-lint` lists missing or malformed function headers and package comments outside doc.go, and
// `-code-unchanged <ref>` fails if anything but comments changed since a git ref (how a comment-only job is checked).
//
// The map holds only function and method signatures, in file and source order. It is a pure function of the code, so
// it cannot be wrong; the explanations live in the function headers, next to the code.
//
// # Function headers
//
// Every function, exported or not, has a doc comment in this shape (gofmt keeps it as written):
//
//	// name does one thing (the one-liner starts with the function's name).
//	//
//	// Notes:
//	//   - an edge case or detail that the code does not make obvious
//	//   - another
//
// Notes hold what a reader cannot see in the code: edge cases, ordering rules, why it is done this way. A function
// with nothing of the kind writes the single line "Notes: none." instead of the list.
//
// # Codemap (auto-generated)
//
// Generated by `go run ./cmd/codemap` from the code; do not edit by hand. Each file lists its function and
// method signatures in source order.
//
//	docgo.go
//	  func replaceSection(src []byte, lines []string) ([]byte, error)
//	  func extractSection(src []byte) (lines []string, ok bool)
//	  func codeBlock(lines []string) []string
//
//	guard.go
//	  func codeUnchanged(root, ref string) ([]string, error)
//	  func onlyPackageClause(src []byte) bool
//	  func stripped(src []byte) (string, error)
//	  func squash(s string) string
//	  func directives(src []byte) string
//	  func git(dir string, args ...string) (string, error)
//
//	lint.go
//	  func lint(pkgs []Pkg) []string
//	  func headerProblems(f Func) []string
//
//	load.go
//	  func load(root string) ([]Pkg, error)
//	  func gitIgnored(root, dir string) bool
//	  func buildPkg(lp *packages.Package, absRoot string) (Pkg, error)
//	  func funcName(fn *ast.FuncDecl) string
//	  func withoutBody(fn *ast.FuncDecl) *ast.FuncDecl
//	  func printNode(fset *token.FileSet, n any) string
//	  func oneLine(s string) string
//
//	main.go
//	  func main()
//	  func readFile(p string) ([]byte, error)
//	  func run(args []string, stdout io.Writer) error
//	  func generate(root string, pkgs []Pkg) (map[string][]byte, error)
//	  func moduleOf(pkgs []Pkg) string
//
//	render.go
//	  func sectionLines(p Pkg) []string
//	  func codemapMD(module string, pkgs []Pkg, sections map[string][]string) string
//	  func dirTitle(p Pkg) string
//	  func tree(rootName string, pkgs []Pkg) string
